"""Rigid knife drive, knife/board contact and external-tool step finalization."""
import warp as wp

@wp.kernel
def accumulate_reaction(enabled: wp.array(dtype=int), reaction: wp.array(dtype=wp.vec3, ndim=2), torque: wp.array(dtype=wp.vec3, ndim=2), position: wp.array(dtype=wp.vec3, ndim=2), linear: wp.array(dtype=wp.vec3, ndim=2), angular: wp.array(dtype=wp.vec3, ndim=2)):
    world, _batch_tid0 = wp.tid()
    if enabled[world] == 0:
        return
    'Sum impulses; angular impulse is about the fixed world origin.'
    linear[world, 0] += reaction[world, 0]
    angular[world, 0] += torque[world, 0] + wp.cross(position[world, 0], reaction[world, 0])

@wp.kernel
def load_external_state(enabled: wp.array(dtype=int), packed: wp.array(dtype=float, ndim=2), tool_pos: wp.array(dtype=wp.vec3, ndim=2), tool_rot: wp.array(dtype=wp.quat, ndim=2), tool_vel: wp.array(dtype=wp.vec3, ndim=2), tool_omega: wp.array(dtype=wp.vec3, ndim=2), mobility: wp.array(dtype=float, ndim=3), linear: wp.array(dtype=wp.vec3, ndim=2), angular: wp.array(dtype=wp.vec3, ndim=2)):
    world, _batch_tid0 = wp.tid()
    if enabled[world] == 0:
        return
    'packed = [position 3, quaternion xyzw 4, velocity 3, angular velocity 3, mobility 36].'
    tool_pos[world, 0] = wp.vec3(packed[world, 0], packed[world, 1], packed[world, 2])
    tool_rot[world, 0] = wp.quat(packed[world, 3], packed[world, 4], packed[world, 5], packed[world, 6])
    tool_vel[world, 0] = wp.vec3(packed[world, 7], packed[world, 8], packed[world, 9])
    tool_omega[world, 0] = wp.vec3(packed[world, 10], packed[world, 11], packed[world, 12])
    for i in range(6):
        for j in range(6):
            mobility[world, i, j] = packed[world, 13 + 6 * i + j]
    linear[world, 0] = wp.vec3(0.0)
    angular[world, 0] = wp.vec3(0.0)

@wp.kernel
def record_pose(enabled: wp.array(dtype=int), position: wp.array(dtype=wp.vec3, ndim=2), rotation: wp.array(dtype=wp.quat, ndim=2), index: int, out: wp.array(dtype=float, ndim=2)):
    world, _batch_tid0 = wp.tid()
    if enabled[world] == 0:
        return
    offset = 9 + 7 * index
    for i in range(3):
        out[world, offset + i] = position[world, 0][i]
    for i in range(4):
        out[world, offset + 3 + i] = rotation[world, 0][i]

@wp.kernel
def store_interval(enabled: wp.array(dtype=int), linear: wp.array(dtype=wp.vec3, ndim=2), angular: wp.array(dtype=wp.vec3, ndim=2), errors: wp.array(dtype=int, ndim=2), out: wp.array(dtype=float, ndim=2)):
    world, _batch_tid0 = wp.tid()
    if enabled[world] == 0:
        return
    'out = [impulse 3, angular impulse about the world origin 3, error flags 3].'
    for i in range(3):
        out[world, i] = linear[world, 0][i]
        out[world, 3 + i] = angular[world, 0][i]
        out[world, 6 + i] = float(errors[world, i])

@wp.kernel
def finish_external_step(enabled: wp.array(dtype=int), reaction: wp.array(dtype=wp.vec3, ndim=2), torque: wp.array(dtype=wp.vec3, ndim=2), board: wp.array(dtype=wp.vec3, ndim=2), speed: wp.array(dtype=float, ndim=2), tool_pos: wp.array(dtype=wp.vec3, ndim=2), tool_vel: wp.array(dtype=wp.vec3, ndim=2), tool_rot: wp.array(dtype=wp.quat, ndim=2), tool_omega: wp.array(dtype=wp.vec3, ndim=2), mobility: wp.array(dtype=float, ndim=3), predict: int, dt: float, linear: wp.array(dtype=wp.vec3, ndim=2), angular: wp.array(dtype=wp.vec3, ndim=2)):
    world, _batch_tid0 = wp.tid()
    if enabled[world] == 0:
        return
    "Accumulate the step impulse, optionally advance the tool, reset sums.\n\n    predict=0 holds pose and twist over the coupling interval (paper III-G).\n    predict=1 applies the step impulse through the external body's mobility\n    and integrates the pose at the resulting twist; the external engine\n    resets the state at the start of the next interval.\n    "
    j = reaction[world, 0]
    tau = torque[world, 0]
    linear[world, 0] += j
    angular[world, 0] += tau + wp.cross(tool_pos[world, 0], j)
    if predict != 0:
        u = wp.spatial_vector(j[0], j[1], j[2], tau[0], tau[1], tau[2])
        dv = wp.vec3(0.0)
        dw = wp.vec3(0.0)
        for row in range(3):
            for col in range(6):
                dv[row] += mobility[world, row, col] * u[col]
                dw[row] += mobility[world, row + 3, col] * u[col]
        tool_vel[world, 0] = tool_vel[world, 0] + dv
        w = tool_omega[world, 0] + dw
        tool_omega[world, 0] = w
        tool_pos[world, 0] = tool_pos[world, 0] + dt * tool_vel[world, 0]
        rate = wp.length(w)
        if rate > 1e-12:
            tool_rot[world, 0] = wp.normalize(wp.quat_from_axis_angle(w / rate, dt * rate) * tool_rot[world, 0])
    reaction[world, 0] = wp.vec3(0.0)
    torque[world, 0] = wp.vec3(0.0)
    board[world, 0] = wp.vec3(0.0)
    speed[world, 0] = 0.0

@wp.func
def vertex(i: int, half: wp.vec3, bevel: float, neck: float):
    j = i % 5
    x = float(0.0)
    z = -half[2]
    if j == 1:
        x = neck
        z += bevel
    elif j == 2:
        x = half[0]
        z = half[2]
    elif j == 3:
        x = -half[0]
        z = half[2]
    elif j == 4:
        x = -neck
        z += bevel
    y = -half[1]
    if i >= 5:
        y = half[1]
    return wp.vec3(x, y, z)

@wp.func
def inv_inertia(q: wp.quat, ii: wp.vec3, torque: wp.vec3):
    return wp.quat_rotate(q, wp.cw_mul(ii, wp.quat_rotate_inv(q, torque)))

@wp.kernel
def step(enabled: wp.array(dtype=int), tool_pos: wp.array(dtype=wp.vec3, ndim=2), tool_vel: wp.array(dtype=wp.vec3, ndim=2), tool_rot: wp.array(dtype=wp.quat, ndim=2), tool_omega: wp.array(dtype=wp.vec3, ndim=2), targets: wp.array(dtype=wp.vec3, ndim=2), rotations: wp.array(dtype=wp.quat, ndim=2), index: int, reaction: wp.array(dtype=wp.vec3, ndim=2), torque: wp.array(dtype=wp.vec3, ndim=2), table_impulse: wp.array(dtype=wp.vec3, ndim=2), dt: float, mass: float, half: wp.vec3, bevel: float, stiffness: float, damping: float, force_limit: float, rotational_stiffness: float, rotational_damping: float, inertia_inverse: wp.vec3, friction: float, free: int, lock_rotation: int, board_half: wp.vec2, neck: float):
    world, _batch_tid0 = wp.tid()
    if enabled[world] == 0:
        return
    'Drive (pose servo, guided translation or none) plus knife/board contact.\n\n    Every internally integrated knife uses this one board contact: the ten blade\n    vertices against the board top z = 0 inside its rectangle (zero half extent:\n    unbounded), the same rectangle the particles and the MuJoCo board use.\n    lock_rotation keeps the guided knife translation-only.\n    '
    x = tool_pos[world, 0] + wp.vec3(0.0)
    q = wp.normalize(tool_rot[world, 0])
    v = tool_vel[world, 0] + wp.vec3(0.0)
    w = tool_omega[world, 0] + wp.vec3(0.0)
    force = wp.vec3(0.0, 0.0, -9.81 * mass)
    servo_torque = wp.vec3(0.0)
    if free == 0:
        target_q = rotations[world, index]
        target_center = targets[world, index] + wp.quat_rotate(target_q, wp.vec3(0.0, 0.0, half[2]))
        force = stiffness * (target_center - x) - damping * v
        norm = wp.length(force)
        if norm > force_limit:
            force *= force_limit / norm
        dq = wp.normalize(target_q * wp.quat_inverse(q))
        if dq[3] < 0.0:
            dq = -dq
        vector = wp.vec3(dq[0], dq[1], dq[2])
        s = wp.length(vector)
        error = 2.0 * vector
        if s > 1e-08:
            error = vector * (2.0 * wp.atan2(s, dq[3]) / s)
        servo_torque = rotational_stiffness * error - rotational_damping * w
    v += (force * dt + reaction[world, 0]) / mass
    ii = inertia_inverse
    if lock_rotation != 0:
        ii = wp.vec3(0.0)
        w = wp.vec3(0.0)
    else:
        local_w = wp.quat_rotate_inv(q, w)
        inertia = wp.vec3(1.0 / ii[0], 1.0 / ii[1], 1.0 / ii[2])
        gyroscopic = wp.quat_rotate(q, wp.cross(local_w, wp.cw_mul(inertia, local_w)))
        w += inv_inertia(q, ii, torque[world, 0] + dt * (servo_torque - gyroscopic))
    normal = wp.vec3(0.0, 0.0, 1.0)
    total = wp.vec3(0.0)
    for sweep in range(6):
        for i in range(10):
            r = wp.quat_rotate(q, vertex(i, half, bevel, neck))
            corner = x + r
            if board_half[0] > 0.0 and wp.abs(corner[0]) > board_half[0] or (board_half[1] > 0.0 and wp.abs(corner[1]) > board_half[1]):
                continue
            gap = corner[2]
            vn = wp.dot(v + wp.cross(w, r), normal)
            desired = -gap / dt
            if gap < 0.0:
                desired *= 0.2
            if vn < desired:
                rn = wp.cross(r, normal)
                effective = 1.0 / mass + wp.dot(rn, inv_inertia(q, ii, rn))
                jn = (desired - vn) / effective
                impulse = jn * normal
                v += impulse / mass
                w += inv_inertia(q, ii, wp.cross(r, impulse))
                vt = v + wp.cross(w, r)
                vt -= wp.dot(vt, normal) * normal
                speed = wp.length(vt)
                if speed > 1e-10:
                    direction = -vt / speed
                    rt = wp.cross(r, direction)
                    wt = 1.0 / mass + wp.dot(rt, inv_inertia(q, ii, rt))
                    jt = wp.min(speed / wt, friction * jn)
                    tangent = jt * direction
                    impulse += tangent
                    v += tangent / mass
                    w += inv_inertia(q, ii, wp.cross(r, tangent))
                total += impulse
    x += dt * v
    speed = wp.length(w)
    if speed > 1e-10:
        q = wp.normalize(wp.quat_from_axis_angle(w / speed, dt * speed) * q)
    tool_pos[world, 0] = x
    tool_vel[world, 0] = v
    tool_rot[world, 0] = q
    tool_omega[world, 0] = w
    table_impulse[world, 0] = total
